          "lead": "В. С. Высоцкий вошёл в русскую литературу не как спокойный рассказчик и не как наблюдатель со стороны. Его голос звучал резко, напряжённо, почти на пределе человеческих возможностей. В его стихах и песнях война перестаёт быть только историческим событием. Она становится внутренним состоянием человека, проверкой совести, мужества и памяти. В. С. Высоцкий не был фронтовиком, но говорил о войне так, будто прожил её сам. Именно поэтому его произведения воспринимались не как стилизация под военную тему, а как живая правда эпохи [1].",
