              "text": "Для многих людей песни В. С. Высоцкого становились и формой внутреннего освобождения. Они позволяли говорить о войне иначе, чем это было принято официально. В магнитофонной культуре 1960-1970-х годов его голос распространялся почти как живая человеческая правда. Люди переписывали плёнки друг другу, слушали песни дома, на кухнях, в общежитиях, в поездах. Голос В. С. Высоцкого становился частью личной памяти поколения [3]."
