              "text": "Военная лирика занимала в этих записях особое место. Люди слушали песни дома, в общежитиях, в студенческих компаниях, в поездах, на кухнях. Магнитофон создавал ощущение личного разговора. Голос В. С. Высоцкого звучал не как официальное выступление по радио, а как непосредственное человеческое обращение."
