              "text": "Отдельные военные песни вызывали настороженность у чиновников. Особенно это касалось «Штрафных батальонов» и некоторых других произведений, где война показывалась без привычной официальной риторики. Концерты иногда отменялись, записи не допускались к эфиру, а критика обвиняла автора в «излишнем натурализме» и «искажении героического образа советского солдата» [12]."
