              "text": "Проблема человека и войны раскрывается и в «Мы вращаем Землю». Здесь солдаты изображаются как люди, несущие на себе тяжесть существования целого мира. Гипербола помогает показать огромную цену человеческого усилия на войне. Победа достигается не отвлечённой исторической силой, а конкретными людьми, которые продолжают двигаться вперёд несмотря на страх и истощение."
