              "text": "Особенно ярко эта проблема раскрывается в «Он не вернулся из боя». Память здесь существует как постоянное ощущение отсутствия рядом другого человека. Герой буквально чувствует пустое место товарища в собственной жизни. Отсутствие становится почти материальным."
