              "title": "Письменное задание",
              "text": "Представьте, что ветеран Великой Отечественной войны впервые слышит военные песни В. С. Высоцкого в 1965 году. Напишите отзыв от его лица. Покажите: * что именно он чувствует; * с чем соглашается; * что кажется ему спорным или неточным; * почему эти песни вызывают у него сильную реакцию. Объём - 12-15 предложений. Важно помнить исторический контекст. Ветеран должен говорить как человек своего времени. Отзыв не должен быть полностью восторженным или полностью отрицательным. Живой человеческий взгляд всегда сложнее и противоречивее. Что проверяет искусственный интеллект: * историческую достоверность позиции; * конкретность реакции на песни; * внутреннюю сложность и неоднозначность мнения; * соответствие эпохе; * эмоциональную убедительность."
